input.command:
S="/c/Users/mgsuk/AppData/Local/Temp/claude/ccf816f539b7556e/84c9502f-eb89-46cc-b4c6-818cd19ea24b/scratchpad"; cd "$S/expC"; cat > inspect2.py <<'EOF'
import sys, json, numpy as np
z = np.load(sys.argv[1])
tree = json.loads(str(z["__tree__"]))
print({k: (v if not isinstance(v,(dict,list)) else type(v).__name__) for k,v in tree.items()})
for k in ("max_frames","fps"): print(k, tree[k])
for name,v in tree["voices"].items(): print("voice", name, z[v["@"]].shape, z[v["@"]].dtype)
print("mean", z[tree["mean"]["@"]].shape)
def shp(w): return w["shape"] if "shape" in w else z[w["@"]].shape
for i,(kind,p) in enumerate(tree["decoder"]["seanet"]):
    if kind=="conv": print(i,kind,shp(p["w"]))
    elif kind=="convt": print(i,kind,shp(p["w"]),"stride",p["stride"])
    elif kind=="res": print(i,kind,shp(p[0]["w"]),shp(p[1]["w"]))
    else: print(i,kind)
EOF
CACTUS_TELEMETRY=0 PYTHONIOENCODING=utf-8 "$S/venv/Scripts/python.exe" -I inspect2.py "$S/models/woof/woof_int8.npz"; sed -n 80,200p "$S/models/woof/README.md"; "$S/venv/Scripts/python.exe" -c "import numpy; numpy.show_config()" 2>&1 | grep -iE "name|version|openblas|mkl" | head; "$S/venv/Scripts/pip.exe" list 2>/dev/null | grep -iE "numpy|torch|numba|onnx|scipy|threadpoolctl|jiwer|pocket|cactus|soundfile"

